import openpyxl, datetime
wb = openpyxl.load_workbook('output.xlsx')
data = wb['Data']
front = wb['Front']
# Build mapping: date -> {agent: F value}
blocks = {}
for r in range(1, data.max_row+1):
    a = data.cell(r,1).value
    if isinstance(a, datetime.datetime):
        blocks[a] = r
# for each date, agents start at date_row+3
for date in [front['B1'].value, front['C1'].value]:
    drow = blocks[date]
    m = {}
    r = drow+3
    while data.cell(r,1).value and not isinstance(data.cell(r,1).value, datetime.datetime):
        m[data.cell(r,1).value] = data.cell(r,6).value
        r += 1
    print(date.date(), m)
"
